+package poll
+
+import (
+	"os"
+	"path/filepath"
+)
+
+// CursorStore persists the poller's last-seen cursor.
+type CursorStore interface {
+	SaveCursor(cursor string) error
+	LoadCursor() (string, error)
+}
+
+// CursorConfig holds the cursor storage settings.
+type CursorConfig struct {
+	FileName string
+}
+
+// DefaultCursorConfig returns the default configuration.
+func DefaultCursorConfig() CursorConfig {
+	return CursorConfig{FileName: "cursor"}
+}
+
+// FileCursorStore stores the cursor in a file under dir.
+type FileCursorStore struct {
+	dir string
+	cfg CursorConfig
+}
+
+// NewFileCursorStore builds a FileCursorStore.
+func NewFileCursorStore(dir string, cfg CursorConfig) *FileCursorStore {
+	return &FileCursorStore{dir: dir, cfg: cfg}
+}
+
+func (s *FileCursorStore) path() string { return filepath.Join(s.dir, s.cfg.FileName) }
+
+func (s *FileCursorStore) SaveCursor(cursor string) error {
+	return os.WriteFile(s.path(), []byte(cursor), 0o600)
+}
+
+func (s *FileCursorStore) LoadCursor() (string, error) {
+	b, err := os.ReadFile(s.path())
+	if os.IsNotExist(err) {
+		return "", nil
+	}
+	return string(b), err
+}
+
+// IsKnownTopic reports whether topic is configured.
+func IsKnownTopic(topic string) bool {
+	for i := 0; i < len(Topics); i++ {
+		if Topics[i] == topic {
+			return true
+		}
+	}
+	return false
+}
